"""Writes art/exports/village-life-c/README.md from model_info.json (labeling-v1 §5 header, then per-item numbers).
python art/source/village-life-c/write_readme.py   (from the repo root)"""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];E=ROOT/'art/exports/village-life-c'
info=json.loads((E/'model_info.json').read_text(encoding='utf-8'))
DESC={'LV01':('竹編雞籠（倒扣的圓頂籠）','練「半球形的竹條排列、底部收邊」。22 條經向竹條從頂上麻繩結往下放射（越往頂越窄，避免在頂上互相疊住），7 圈緯向竹條一上一下穿過；底部一圈厚收邊，八處用麻繩綁住（繩子只繞外、上、內三面，兩端塞進收邊，不從地面下穿過）；頂上麻繩結加一個兩股絞成的提環；一條較新的補條綁在斷掉的竹條上。稻草卡在底部縫裡、兩根羽毛在收邊旁（Detail_）。','cand-3（92）'),
      'LV02':('竹掃帚與木畚箕','練「細枝束成一把的輪廓、木板拼接」。cand-3 把掃帚畫成直立，但提示詞和工作包高度 0.3 m 都是平放，所以掃帚平躺在畚箕旁：64 根細枝（部分分叉，兩端收細）從綁好的芯末端散成扁扇形，三道麻繩綁住；竹柄有竹節，柄頂纏繩垂一段繩尾、中段一圈布用兩條繩交叉綁住。畚箕三片底板、兩片三角側板、後板和 ∩ 形握把（交叉麻繩綁住），底板角落釘一塊補板。','cand-3（90）'),
      'LV03':('靠牆的竹梯','練「竹節、橫檔綁繩的重複節奏」。兩根粗竹竿下寬上窄、竹節間距不一；七根橫檔每個交點都用同一種綁法（竹竿上下各纏兩圈，再兩圈斜繞在正面交叉成 X）；第四根是換新的淺色竹橫檔；橫檔中段被踩得較暗、較滑，竿腳髒、帶一點苔。工作包尺寸深 0.1 m，所以模型是直立的，靠牆的角度在擺放時整件傾斜。','cand-4（93）'),
      'LV04':('竹編吊籃（掛著晾菜乾）','練「淺籃和吊繩、裡面一點乾菜」。淺圓籃（直徑 0.46 m）是一個薄殼，竹篾的一上一下編織畫在貼圖上；籃緣一圈粗竹篾每 30° 用細篾綁住，一邊略垂；三條麻繩從籃緣打結往上收到一個繩結，再一個掛圈（總高 0.77 m）；籃裡四片乾菜葉、五根紅辣椒；籃側一塊灰布補丁。原點在籃底：單獨放是籃子著地、繩子立起，擺放時由核心組掛上。','cand-1（92）'),
      'LV05':('醃菜甕三個（大中小，有蓋、壓石）','練「和 BM03 陶罐不同：寬口、厚蓋、蓋上壓一塊石頭」。三個甕各自分開放、不焊在一起，輪廓都不同：大甕肩寬、中甕直身、小甕矮胖；都是寬口、口沿一圈未上釉的陶，蓋上厚陶蓋、壓一顆平滑的河石；大甕蓋緣缺一角。深褐釉面上從肩部往下的流痕、甕腳的濕土和苔畫在貼圖上。和 BM03 的並排在 `art/previews/village-life-c/compare/LV05-vs-BM03-*`。','cand-2（92）'),
      'LV06':('劈柴木墩與柴刀','練「年輪切面、刀砍的痕、刀插在木墩上」。木墩高 0.4 m、底部根部外撇成五瓣，淺色風化木帶直向灰紋，九片樹皮從根部往上、邊緣參差、上緣往外翹；頂面年輪切面（放射裂紋），交叉的刀痕畫在貼圖上；一把寬刃柴刀在自己的平面裡斜插進頂面（刃口後端埋 1.2 cm、前端 6 cm），木柄纏布、垂兩條布尾；腳邊三塊劈柴，木屑（Detail_）。','cand-4（93）'),
      'LV07':('葫蘆水瓢與木掛勾','練「葫蘆對半剖的曲面、勾子」。瓢是一個梨形葫蘆沿長向剖開的一半：4 mm 厚的殼，剖口朝前，內面較深褐、較滑；瓢柄是葫蘆頸，頂端穿一個孔。四塊直板拼成的舊木板（板縫、兩顆鐵釘、上緣參差），一根短木樁斜插往上；麻繩圈穿過瓢柄的孔、打結後掛在木樁上（繩尾 Detail_）；瓢緣一道裂縫用三針細繩縫住（Detail_）。木樁下的水漬、木板上緣的苔畫在貼圖上。掛牆的東西：瓢底是 z = 0，木板背面平的、貼牆，擺放時整件移到牆上。','cand-1（93）'),
      'LV08':('斗笠與蓑衣掛在木架上','練「斗笠的圓錐、蓑衣的一層層草片」。斗笠是有厚度的淺圓錐殼，戴在方立柱頂上（柱角剛好頂住斗笠內面），竹篾編紋在貼圖上，緣口一圈參差的破篾（Detail_），頂上一個竹鈕；蓑衣五層草片，每層的上緣藏在上一層下面、下半往外張，越往下越寬，下緣剪成參差的草尾，前面開口看得到立柱；第一層的上緣收攏在柱上，用麻繩綁住，喉口一個蝴蝶結、兩條繩垂下帶穗；兩塊布補丁畫在貼圖上。木架：兩條橫腳、一根橫樑、柱腳兩塊楔木、柱下段纏三圈麻繩，兩根短木樁（右邊那根常用，較淺較滑）。工作包深度上限 0.4 m，斗笠只能做 0.38 m 寬（三視圖約 0.6 m）。','cand-2（93）'),
      'LV09':('竹鳥籠掛在短竿上（空籠）','練「圓柱細竹條、頂部提環」。籠身 36 根細竹條平均排一圈，上段彎進圓頂收到頂上的深色木鈕，三道橫箍（最下一道在門口斷開）；深色木底圈和籠底板；正面一扇小門（框和三根竹條）用細繩鉸著、往外開。「提環」：木鈕上一個鐵眼，竹環穿過鐵眼，竹環再掛在橫竿下的麻繩圈裡，三者真的互扣，彼此靠著（0.3 mm）。竹竿立在粗石塊裡，頂上一根橫竿、一根斜撐，都用麻繩綁；竿中段纏一塊舊布（垂下的布尾 Detail_）。空籠，沒有鳥。LOD2 改用一個 18 邊的圓柱加圓頂、竹條畫在貼圖上（alpha clip）：細竹條減面後會碎。','cand-4（93）'),
      'LV10':('草鞋與木屐各一雙','練「小物件的比例、編織紋用貼圖表現」。照真實尺寸：草鞋長 0.24 m，木屐長 0.225 m、兩個齒高 3.4 cm。草鞋是一片平的鞋底加一圈粗草辮邊，鞋底的人字編紋、腳跟和前掌壓扁變深、草辮邊的斜紋都畫在貼圖上，不逐根建；木屐是一塊淺色舊木板、底下兩個齒，齒和板底沾泥、板面的腳印畫在貼圖上。四隻鞋都用同一種深藍布帶：兩條從腳趾的結拉到兩側，一根柱插進鞋底；結上散開的線頭是 Detail_。每隻鞋各自分開，兩雙稍微歪著放。','cand-1（92）'),
      'LV11':('磨刀石座（長條石放在木凳上）','練「石頭中間磨凹的形狀、木凳榫接」。磨刀石長 0.58 m，頂面沿長向磨成一道平滑的凹（中間深 4.6 cm，兩端高；橫向也略呈 U 形），兩側和端面是粗糙的斷面；凹面較亮、較滑。木凳：厚凳面，四隻腳的榫頭穿出凳面、比凳面高 3.5 mm 看得到方形端面；前後兩條牙板、兩側下橫檔都穿過凳腳。左端一個陶碗盛水，石頭下的濕痕畫在貼圖上；前牙板掛一塊布，後牙板上釘一塊斜補板。','cand-1（93）'),
      'LV12':('稻草蛋籃（籃裡墊稻草和幾顆蛋）','練「籃的編織、稻草的亂、蛋的乾淨圓形」。小圓籃（直徑 0.31 m）是有厚度的殼，竹篾一上一下的編紋在貼圖上，粗籃緣和底圈都是整圈閉合的管；右前一側往內壓凹、那裡的籃緣稍低。籃裡一層稻草墊，64 根草尾從裡面翹出、跨過籃緣往外垂，少數直立彎下，26 根散草躺在草墊上。六顆奶白色的蛋（5.4–6.0 cm）都是平滑的蛋形、一頭稍尖，躺在草墊上，彼此不碰。籃側（背面）一塊布補丁畫在貼圖上。','cand-4（93）'),
      'LV13':('竹蒸籠一疊（三層加蓋）','練「圓形竹圈的重複、層與層的接縫」（11/08 工作包）。三層用同一種做法：一圈竹片圍成的圈、底下一圈較厚的腳圈、裡面一張編織的籠底（編紋在貼圖上），圈上四條直向綁片和一段搭接的接頭；上一層的腳圈套在下一層的上緣上，就是層與層的接縫，每層稍微轉一點、偏幾公釐。蓋子是編織的淺圓頂，加一圈蓋緣、頂上竹鈕和提環，蓋緣一圈破篾翹起（Detail_）。最下一層被蒸氣燻深在貼圖上。','cand-3（93）'),
      'LV14':('木提盒（三層食盒）','練「方盒疊放、提把的弧線、漆面磨損」。底座、三層盒和蓋疊起來，每層底下有一圈子口坐進下一層（兩層之間看得到一道深色縫），中層偏 5 mm。提把是兩根立柱接一條彎過頂的弧形把，頂上纏麻繩，黃銅銷子從立柱穿進每一層；四角黃銅包角；側面一塊補板。暗紅漆只在邊、角和把手上磨掉露出木色（貼圖），不畫花紋。','cand-2（93）'),
      'LV15':('陶油燈台','練「高腳燈座的旋轉體、燈芯碟」。燈座是一條輪廓轉出來的實心旋轉體：喇叭形底座、細長燈柱、中段一道腰箍、上端的托；燈碟是有厚度的淺碟，碟內上釉較深，裡面一層油，一根搓成的棉燈芯從碟心斜搭到碟緣。燈芯上方燻黑、油沿燈柱流下的痕在貼圖上；底座缺一角是切出來的。','cand-3（93）'),
      'LV16':('木洗臉盆架與木盆','練「三腳架的榫接、木盆的箍」。三隻往外斜的方腳，頂上三根托檔、下段三根橫檔，每根都穿過腳、榫頭露在外面；盆坐在頂上的托檔上。木盆是 16 片木條圍成的圓錐盆（片與片之間有細縫）加一塊圓底，兩道竹箍、搭接處用麻繩綁住；前腳上一根木釘掛一條粗布。盆身水漬在貼圖上。盆連箍寬 0.38 m，配合工作包的深度 0.4 m。','cand-1（93）'),
      'LV17':('書桌小物（筆架、硯台、紙鎮）','練「三件小東西的比例和擺放，不寫字」。一塊矮木托上：後面一個筆架（兩根立柱站在腳座上、一根橫樑），三支毛筆用黃銅小鉤掛著（筆桿、筆箍、筆毛分開做）；前左一方黑硯，切出一個淺墨池和一個較深的水池，池裡乾墨在貼圖上；前右一條古銅紙鎮，霧面帶一點綠鏽。全部不寫字、不刻字。照工作包高度 0.2 m 調整比例。','cand-1（92）'),
      'LV18':('木算盤','練「很多一樣的珠子排整齊（用陣列）」。深色硬木框、一根橫樑、13 根細桿；珠子只做一顆（扁圓旋轉體），用兩個 Array 修改器排出來：梁下 5 顆 × 13 檔、梁上 2 顆 × 13 檔，共 91 顆，再套用；一顆珠子用切塊切出缺角。工作包尺寸是 w × d × h = 0.35 × 0.12 × 0.05 m，所以算盤平放（框面朝上）。框角磨淺在貼圖上。','cand-3（93）'),
      'LV19':('竹簸箕（曬穀用）','練「一邊開口的淺籃形」；和竹篩、晾茶竹匾不同。底面和後牆、兩側牆是一張連續的薄殼，從後面約 13 cm 高往前降到開口貼地，開口那邊是平的倒口；沿後面和兩側一條粗竹緣，九處用麻繩綁住，倒口沿一條薄竹壓邊。編紋在貼圖上，倒口磨深；一塊補片；籃裡十幾粒米（Detail_）。竹篩是圓的、四邊一樣高，竹匾是平的圓匾，一眼分得開。','cand-4（93）'),
      'LV20':('蒲扇與竹扇各一','練「扁平物件的厚度、扇面紋路用貼圖」。兩把並排平放：蒲扇是一片 3 mm 的葉面、外圈竹緣、圓木柄纏布，葉面放射葉脈在貼圖上，葉緣幾根破葉（Detail_）；摺扇開約 100°，10 根竹骨疊在黃銅鉚釘上（一根正一根反斜 12°，疊起來不黏在同一面），兩根邊骨較厚，扇面是一張有摺痕的白紙，不畫畫、不寫字。三視圖四張都沒把兩把扇子好好並排，選了把兩把都畫出來的 cand-3。','cand-3（90）')}
rows=[]
for k in sorted(info):
    d=info[k];l=d['lods'];name,desc,ref=DESC[k]
    tex=', '.join(sorted({f'{w}×{h}' for w,h in l['LOD0']['textures_px'].values()}))
    det=', '.join(d['detailObjects']) if d['detailObjects'] else '無'
    rows.append(f"### {k} {name}（{d['name']}，{d['version']}）\n\n{desc}\n\n"
      f"| 項目 | 數字 |\n|---|---|\n| 三視圖 | `art/references/{k}/`，選用 {ref} |\n"
      f"| 尺寸（寬 × 深 × 高） | {d['dimensions_xyz_m'][0]} × {d['dimensions_xyz_m'][1]} × {d['dimensions_xyz_m'][2]} m（上限 {' × '.join(str(x) for x in d['size_limit_xyz_m'])} m） |\n"
      f"| 三角面 LOD0 / LOD1 / LOD2 | {l['LOD0']['triangles']:,} / {l['LOD1']['triangles']:,} / {l['LOD2']['triangles']:,}（不含 Detail_：{l['LOD0']['triangles_without_detail']:,} / {l['LOD1']['triangles_without_detail']:,} / {l['LOD2']['triangles_without_detail']:,}） |\n"
      f"| 物件數（每個 LOD） | {l['LOD0']['objects']}（本體 1 + {det}） |\n"
      f"| 材質數 | 1（`{d['material']}`，本體和 Detail_ 共用） |\n| 貼圖 | Albedo、Normal、ORM、MaskURP 各一張，{tex} |\n"
      f"| minTier | {d['minTier']} |\n| 檔案 | `{d['files']['fbx']}`（LOD0–2）、`{d['files']['glb']}`（LOD0）、`{d['files']['blend']}` |\n")
